mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("n=5 adds=(1,5),(3,2),(4,4) query=3","7"),
        ("n=4 adds=(1,3),(2,4),(4,8) query=4","15"),
        ("n=1 adds=(1,7) query=1","7"),
        ("n=5 adds=(1,2),(5,9) query=4","2"),
        ("n=3 adds=(2,5),(2,-2) query=3","3"),
        ("  \nn=5 adds=(1,5),(3,2),(4,4) query=3\n  ","7"),
        ("\nn=3 adds=(2,5),(2,-2) query=3\n","3")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS fenwick-tree");
}
